command(node --import tsx -e "
import { db } from './src/db/index.ts';
import { dreams, dreamImages, dreamTags, tags, comments, users } from './src/db/schema.ts';
import { eq, desc } from 'drizzle-orm';

async function test() {
  console.log('🔍 Testing Next.js Drizzle integration with real DB...');

  // 1. Get recent dreams
  const recentDreams = await db.query.dreams.findMany({
    limit: 3,
    orderBy: [desc(dreams.createdAt)],
    with: {
      user: {
        columns: { id: true, username: true, avatar: true }
      },
      images: true,
      comments: { limit: 2 },
      tags: {
        with: { tag: true }
      }
    }
  });

  console.log('✅ Query dreams success! Count:', recentDreams.length);
  for (const d of recentDreams) {
    console.log({
      id: d.id,
      title: d.title,
      author: d.user?.username,
      imageCount: d.images.length,
      commentCount: d.comments.length,
      tagCount: d.tags.length,
      tags: d.tags.map(t => t.tag.name)
    });
  }
}
test().then(() => process.exit(0)).catch(e => { console.error('Drizzle query failed:', e); process.exit(1); });
")

command(node -e '
const fs = require("fs");
const html = fs.readFileSync(".deploy/index.html", "utf-8");
const scripts = html.match(/<script[\s\S]*?<\/script>/g) || [];
console.log("Total script tags in .deploy/index.html:", scripts.length);
scripts.forEach((tag, i) => {
  const code = tag.replace(/^<script[^>]*>/, "").replace(/<\/script>$/, "");
  const vm = require("vm");
  new vm.Script(code, { filename: `script_${i}.js` });
  console.log(`Script ${i} compiled successfully (${code.length} bytes)`);
});
')

